//! DM pairing CLI commands.//!//! Manage pairing requests for channels (Telegram, Slack, etc.).use clap::Subcommand;use crate::pairing::PairingStore;/// Pairing subcommands.#[derive(Subcommand, Debug, Clone)]pub enum PairingCommand {    /// List pending pairing requests    List {        /// Channel name (e.g., telegram, slack)        #[arg(required = true)]        channel: String,        /// Output as JSON        #[arg(long)]        json: bool,    },    /// Approve a pairing request by code    Approve {        /// Channel name (e.g., telegram, slack)        #[arg(required = true)]        channel: String,        /// Pairing code (e.g., ABC12345)        #[arg(required = true)]        code: String,    },}/// Run pairing CLI command.pub fn run_pairing_command(cmd: PairingCommand) -> Result<(), String> {    run_pairing_command_with_store(&PairingStore::new(), cmd)}/// Run pairing CLI command with a given store (for testing).